# Lempel construction for Costas array of order q-2 = 15 with q=17
p = 17
# primitive root of 17: 3
g = 3
powers = {}
for i in range(1, p):
    powers[pow(g, i, p)] = i  # map value -> exponent

# Build Costas array: row r (0-indexed) at column c (0-indexed) where
# g^(c+1) + g^(r+1) == 1 mod p
n = p - 2
perm = [None]*n
for c in range(n):
    val = (1 - pow(g, c+1, p)) % p
    if val == 0: 
        continue
    if val in powers:
        j = powers[val]
        if 1 <= j <= n:
            perm[c] = j-1

print(perm)

# Verify Costas property
def check_costas(perm):
    n = len(perm)
    if sorted(perm) != list(range(n)):
        return False, "not a permutation"
    vectors = set()
    for c1 in range(n):
        for c2 in range(c1+1, n):
            v = (c2-c1, perm[c2]-perm[c1])
            if v in vectors:
                return False, f"duplicate {v}"
            vectors.add(v)
    return True, "OK"

print(check_costas(perm))
